// Generates dist/activity.svg — a lime-themed GitHub activity card.
// Runs in GitHub Actions (Node 20). Data: GitHub GraphQL API via GITHUB_TOKEN.
// Local preview: node cards.mjs --mock
import { writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const FONTS = {
  'anton.woff2': '',
  'grotesk.woff2': '',
};
const font = (f) => FONTS[f];
const USER = process.env.GH_USER || 'Arsalanimran007';
const OUT = process.env.OUT_DIR || 'dist';
const C = { bg: '#0b0b0b', card: '#141413', line: '#262624', ink: '#f4f4f0', mute: '#8a8a82', lime: '#c6f432' };
const LEVELS = ['#1c1c1a', '#2c3a0c', '#4f6b12', '#8fb722', '#c6f432'];

const H = () => ({ Authorization: `bearer ${process.env.GITHUB_TOKEN}`, 'Content-Type': 'application/json', 'User-Agent': 'profile-cards' });

async function gql(query) {
  const r = await fetch('https://api.github.com/graphql', { method: 'POST', headers: H(), body: JSON.stringify({ query, variables: { login: USER } }) });
  const j = await r.json();
  if (j.errors) console.warn('GraphQL warnings:', JSON.stringify(j.errors));
  return j.data?.user || null;
}

async function rest(path) {
  const r = await fetch('https://api.github.com' + path, { headers: H() });
  if (!r.ok) { console.warn('REST', path, r.status); return null; }
  return r.json();
}

async function fetchData() {
  const d = { contributions: 0, commits: 0, repos: 0, stars: 0, prs: 0, weeks: [], langs: {} };

  // 1) Contribution calendar (GraphQL, public data)
  const cal = await gql(`query($login:String!){ user(login:$login){ contributionsCollection{ totalCommitContributions
    contributionCalendar{ totalContributions weeks{ contributionDays{ contributionCount } } } } } }`);
  if (cal) {
    const cc = cal.contributionsCollection;
    d.contributions = cc.contributionCalendar.totalContributions;
    d.commits = cc.totalCommitContributions;
    d.weeks = cc.contributionCalendar.weeks.map((w) => w.contributionDays.map((x) => x.contributionCount));
  }

  // 2) Pull requests (search API)
  const pr = await rest(`/search/issues?q=author:${USER}+type:pr&per_page=1`);
  if (pr) d.prs = pr.total_count;

  // 3) Public repos + languages (REST)
  const repos = (await rest(`/users/${USER}/repos?per_page=100&type=owner`)) || [];
  const own = repos.filter((r) => !r.fork);
  d.repos = own.length;
  d.stars = own.reduce((s, r) => s + r.stargazers_count, 0);
  for (const r of own) {
    const l = await rest(`/repos/${USER}/${r.name}/languages`);
    if (l) for (const [k, v] of Object.entries(l)) d.langs[k] = (d.langs[k] || 0) + v;
  }
  if (!d.weeks.length) d.weeks = Array.from({ length: 52 }, () => Array(7).fill(0));
  return d;
}

function mockData() {
  const weeks = Array.from({ length: 53 }, (_, w) => Array.from({ length: 7 }, (_, d) => ((w * 7 + d) * 37 % 11 > 6 ? (w * d) % 9 : 0)));
  return { contributions: 412, commits: 318, repos: 18, stars: 9, prs: 24, weeks, langs: { TypeScript: 52, JavaScript: 31, CSS: 9, HTML: 5, Python: 3 } };
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;');

function render(d) {
  const W = 1000, H = 300;
  const max = Math.max(1, ...d.weeks.flat());
  const lvl = (n) => (n === 0 ? 0 : Math.min(4, Math.ceil((n / max) * 4)));
  const weeks = d.weeks.slice(-52);
  const cell = 9, gap = 2, hx = 372, hy = 104;
  let cells = '';
  weeks.forEach((w, i) => w.forEach((n, j) => {
    cells += `<rect x="${hx + i * (cell + gap)}" y="${hy + j * (cell + gap)}" width="${cell}" height="${cell}" rx="2" fill="${LEVELS[lvl(n)]}" style="animation-delay:${(i * 18)}ms"/>`;
  }));
  const stats = [
    [d.contributions, 'Contributions'],
    [d.commits, 'Commits'],
    [d.repos, "Public repos"],
    [d.prs, 'Pull requests'],
  ];
  let st = '';
  stats.forEach(([v, l], i) => {
    const x = 40 + (i % 2) * 150, y = 168 + Math.floor(i / 2) * 74;
    st += `<text x="${x}" y="${y}" class="num">${esc(v.toLocaleString('en-US'))}</text><text x="${x}" y="${y + 22}" class="lab">${esc(l)}</text>`;
  });
  const total = Object.values(d.langs).reduce((a, b) => a + b, 0) || 1;
  const top = Object.entries(d.langs).sort((a, b) => b[1] - a[1]).slice(0, 5);
  const shades = [C.lime, '#8fb722', '#5c7d15', '#7a7a72', '#4a4a45'];
  const bx = 372, bw = 572, by = 228;
  let off = 0, bar = '', legend = '', legendX = bx;
  top.forEach(([name, v], i) => {
    const pct = v / total, w = Math.max(2, pct * bw);
    bar += `<rect x="${bx + off}" y="${by}" width="${w}" height="10" fill="${shades[i]}"/>`;
    off += w;
    const lx = legendX;
    legendX += name.length * 7.6 + 62;
    legend += `<rect x="${lx}" y="${by + 30}" width="9" height="9" rx="2" fill="${shades[i]}"/><text x="${lx + 15}" y="${by + 39}" class="leg">${esc(name)} <tspan fill="${C.mute}">${(pct * 100).toFixed(0)}%</tspan></text>`;
  });
  const date = new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" role="img" aria-label="GitHub activity for ${USER}">
<style>
@font-face{font-family:A;src:url(data:font/woff2;base64,${font('anton.woff2')}) format('woff2')}
@font-face{font-family:G;src:url(data:font/woff2;base64,${font('grotesk.woff2')}) format('woff2');font-weight:300 700}
text{font-family:G,Arial,sans-serif;fill:${C.ink}}
.eb{font-size:12px;font-weight:500;letter-spacing:.16em;fill:${C.mute}}
.h{font-family:A,Impact,sans-serif;font-size:34px;letter-spacing:.01em}
.num{font-family:A,Impact,sans-serif;font-size:44px}
.lab{font-size:11px;font-weight:500;letter-spacing:.12em;fill:${C.mute};text-transform:uppercase}
.leg{font-size:12px;font-weight:600}
.cal rect{opacity:0;animation:in .5s ease forwards}
@keyframes in{to{opacity:1}}
.dot{animation:pulse 1.6s ease-in-out infinite}
@keyframes pulse{50%{opacity:.25}}
</style>
<rect width="${W}" height="${H}" rx="18" fill="${C.card}" stroke="${C.line}"/>
<text x="40" y="44" class="eb">(06) GITHUB ACTIVITY</text>
<circle cx="${W - 234}" cy="40" r="4" fill="${C.lime}" class="dot"/>
<text x="${W - 40}" y="44" class="eb" text-anchor="end">UPDATED ${esc(date.toUpperCase())}</text>
<text x="40" y="88" class="h">SHIPPING <tspan fill="${C.lime}">CONSISTENTLY</tspan></text>
<line x1="336" y1="104" x2="340" y2="268" stroke="${C.line}"/>
${st}
<text x="40" y="118" class="eb" style="font-size:11px">LAST 12 MONTHS</text>
<text x="${hx}" y="88" class="eb" style="font-size:11px">CONTRIBUTION CALENDAR · 52 WEEKS</text>
<g class="cal">${cells}</g>
<text x="${bx}" y="${by - 10}" class="eb" style="font-size:11px">TOP LANGUAGES · BY CODE SIZE</text>
<clipPath id="bc"><rect x="${bx}" y="${by}" width="${bw}" height="10" rx="5"/></clipPath>
<g clip-path="url(#bc)"><rect x="${bx}" y="${by}" width="${bw}" height="10" fill="#1c1c1a"/>${bar}</g>
${legend}
</svg>`;
}

const data = process.argv.includes('--mock') ? mockData() : await fetchData();
mkdirSync(OUT, { recursive: true });
writeFileSync(join(OUT, 'activity.svg'), render(data));
console.log('wrote', join(OUT, 'activity.svg'), JSON.stringify({ ...data, weeks: undefined }));
